mapper.select:
select count(*) from sys_notice_read r
inner join sys_notice n on n.id = r.notice_id and n.del_flag = 0
where r.notice_id = #{noticeId} and r.user_id = #{userId}

select u.id as userId, u.user_name as userName, u.nick_name as nickName, d.dept_name as deptName, u.phone_number as phoneNumber, r.read_time as readTime from sys_notice_read r inner join sys_notice n on n.id = r.notice_id and n.del_flag = 0 inner join sys_user u on u.id = r.user_id and u.del_flag = '0' left join sys_dept d on d.id = u.dept_id where r.notice_id = #{query.noticeId}
and ( u.user_name like concat('%', #{query.searchValue}, '%') or u.nick_name like concat('%', #{query.searchValue}, '%') )
order by r.read_time desc, u.id asc
